begin;
create table public.candidate_placements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,candidate_id uuid not null references public.candidates,job_id uuid not null references public.jobs,created_by uuid not null references auth.users,status text not null default 'submitted' check(status in ('submitted','reviewing','interview','offer','hired','rejected','withdrawn')),source text not null default 'manual' check(length(source) between 1 and 120),notes text not null default '' check(length(notes)<=8000),created_at timestamptz not null default now(),unique(candidate_id,job_id));
alter table public.candidate_placements enable row level security;
create function public.can_manage_placement(placement uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.candidate_placements p where p.id=placement and public.owns_job(p.job_id) and public.can_read_candidate(p.candidate_id))$$;
revoke all on function public.can_manage_placement(uuid) from public,anon;grant execute on function public.can_manage_placement(uuid) to authenticated;
create policy placement_read on public.candidate_placements for select to authenticated using(public.is_member(organization_id) and public.can_read_candidate(candidate_id));
create policy placement_insert on public.candidate_placements for insert to authenticated with check(created_by=auth.uid() and status='submitted' and public.owns_job(job_id) and public.can_read_candidate(candidate_id) and exists(select 1 from public.jobs j where j.id=job_id and j.organization_id=candidate_placements.organization_id and j.status='open') and exists(select 1 from public.candidates c where c.id=candidate_id and c.organization_id=candidate_placements.organization_id));
create policy placement_update on public.candidate_placements for update to authenticated using(public.can_manage_placement(id)) with check(public.can_manage_placement(id));
revoke all on public.candidate_placements from anon,authenticated;grant select,insert(organization_id,candidate_id,job_id,created_by,source,notes) on public.candidate_placements to authenticated;grant update(status,notes,source) on public.candidate_placements to authenticated;
create table public.placement_activity(id uuid primary key default gen_random_uuid(),placement_id uuid not null references public.candidate_placements,status text not null,actor_id uuid references auth.users,created_at timestamptz not null default now());
alter table public.placement_activity enable row level security;
create policy placement_activity_read on public.placement_activity for select to authenticated using(exists(select 1 from public.candidate_placements p where p.id=placement_id));
revoke all on public.placement_activity from anon,authenticated;grant select on public.placement_activity to authenticated;
create function public.log_placement_activity() returns trigger language plpgsql security definer set search_path='' as $$begin if TG_OP='INSERT' or old.status is distinct from new.status then insert into public.placement_activity(placement_id,status,actor_id) values(new.id,new.status,auth.uid());end if;return new;end$$;
create trigger protect_placement_withdrawn before update on public.candidate_placements for each row execute function public.protect_withdrawn();
create trigger placement_activity after insert or update on public.candidate_placements for each row execute function public.log_placement_activity();
create table public.placement_interviews(id uuid primary key default gen_random_uuid(),placement_id uuid not null references public.candidate_placements,starts_at timestamptz not null,notes text not null default '' check(length(notes)<=4000),cancelled_at timestamptz,created_at timestamptz not null default now());
alter table public.placement_interviews enable row level security;
create policy placement_interview_read on public.placement_interviews for select to authenticated using(exists(select 1 from public.candidate_placements p where p.id=placement_id));
create policy placement_interview_insert on public.placement_interviews for insert to authenticated with check(public.can_manage_placement(placement_id));
create policy placement_interview_update on public.placement_interviews for update to authenticated using(public.can_manage_placement(placement_id)) with check(public.can_manage_placement(placement_id));
revoke all on public.placement_interviews from anon,authenticated;grant select,insert on public.placement_interviews to authenticated;grant update(starts_at,notes,cancelled_at) on public.placement_interviews to authenticated;
alter table public.interviews add column cancelled_at timestamptz;
create function public.cancel_interview(interview uuid) returns void language plpgsql security definer set search_path='' as $$declare app uuid;begin select application_id into strict app from public.interviews where id=interview;if not public.can_manage_application(app) then raise exception 'Not permitted';end if;update public.interviews set cancelled_at=now() where id=interview and cancelled_at is null;if found then insert into public.notifications(user_id,application_id,kind) select candidate_id,id,'interview_cancelled' from public.applications where id=app;end if;end$$;
revoke all on function public.cancel_interview(uuid) from public,anon;grant execute on function public.cancel_interview(uuid) to authenticated;
create table public.management_audit(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations,actor_id uuid references auth.users,entity_type text not null,entity_id uuid,action text not null,details jsonb not null default '{}',created_at timestamptz not null default now());
alter table public.management_audit enable row level security;
create policy management_audit_read on public.management_audit for select to authenticated using(public.is_platform_admin() or public.has_role(organization_id,array['owner','admin']));
revoke all on public.management_audit from anon,authenticated;grant select on public.management_audit to authenticated;
create function public.log_management_change() returns trigger language plpgsql security definer set search_path='' as $$declare org uuid;entity uuid;info jsonb;begin
 if TG_TABLE_NAME='jobs' then org=new.organization_id;entity=new.id;info=jsonb_build_object('title',new.title,'status',new.status);
 elsif TG_TABLE_NAME='external_jobs' then entity=new.id;info=jsonb_build_object('title',new.title,'publication_status',new.publication_status,'source',new.source_id);
 elsif TG_TABLE_NAME='memberships' then org=new.organization_id;entity=new.user_id;info=jsonb_build_object('role',new.role);
 elsif TG_TABLE_NAME='candidate_placements' then org=new.organization_id;entity=new.id;info=jsonb_build_object('status',new.status);
 end if;
 insert into public.management_audit(organization_id,actor_id,entity_type,entity_id,action,details) values(org,auth.uid(),TG_TABLE_NAME,entity,lower(TG_OP),info);return new;end$$;
create trigger audit_jobs after insert or update on public.jobs for each row execute function public.log_management_change();
create trigger audit_imported_jobs after insert or update on public.external_jobs for each row execute function public.log_management_change();
create trigger audit_memberships after insert or update on public.memberships for each row execute function public.log_management_change();
create trigger audit_placements after insert or update on public.candidate_placements for each row execute function public.log_management_change();
create table public.job_categories(id uuid primary key default gen_random_uuid(),name_he text not null unique check(length(name_he) between 1 and 120),name_en text not null unique check(length(name_en) between 1 and 120));
create table public.role_aliases(id uuid primary key default gen_random_uuid(),category_id uuid not null references public.job_categories,alias text not null check(length(alias) between 1 and 120),alias_key text generated always as(lower(trim(alias))) stored unique);
alter table public.job_categories enable row level security;alter table public.role_aliases enable row level security;
create policy category_read on public.job_categories for select using(true);create policy alias_read on public.role_aliases for select using(true);
create policy category_write on public.job_categories for all to authenticated using(public.is_platform_admin()) with check(public.is_platform_admin());
create policy alias_write on public.role_aliases for all to authenticated using(public.is_platform_admin()) with check(public.is_platform_admin());
revoke all on public.job_categories,public.role_aliases from anon,authenticated;grant select on public.job_categories,public.role_aliases to anon,authenticated;grant insert,update on public.job_categories,public.role_aliases to authenticated;
commit;
